import java.util.*;

class Solution {
    private Map<Long, Integer> memo = new HashMap<>();

    private int dfs(int rem, int[] counts, int batchSize) {
        long key = rem;
        for (int i = 1; i < batchSize; ++i) {
            key = key * 31 + counts[i];
        }
        if (memo.containsKey(key)) return memo.get(key);
        int res = 0;
        for (int i = 1; i < batchSize; ++i) {
            if (counts[i] > 0) {
                counts[i]--;
                int gained = (rem == 0) ? 1 : 0;
                int nxtRem = (rem + i) % batchSize;
                res = Math.max(res, gained + dfs(nxtRem, counts, batchSize));
                counts[i]++;
            }
        }
        memo.put(key, res);
        return res;
    }

    public int maxHappyGroups(int batchSize, int[] groups) {
        int[] counts = new int[batchSize];
        for (int g : groups) counts[g % batchSize]++;
        int ans = counts[0];
        for (int i = 1; i <= batchSize / 2; ++i) {
            if (i == batchSize - i) {
                int pairs = counts[i] / 2;
                ans += pairs;
                counts[i] -= pairs * 2;
            } else {
                int pairs = Math.min(counts[i], counts[batchSize - i]);
                ans += pairs;
                counts[i] -= pairs;
                counts[batchSize - i] -= pairs;
            }
        }
        return ans + dfs(0, counts, batchSize);
    }
}

