var maxHappyGroups = function(batchSize, groups) {
    const counts = Array(batchSize).fill(0);
    for (const g of groups) counts[g % batchSize]++;

    let ans = counts[0];
    for (let i = 1; i <= Math.floor(batchSize / 2); ++i) {
        if (i === batchSize - i) {
            const pairs = Math.floor(counts[i] / 2);
            ans += pairs;
            counts[i] -= pairs * 2;
        } else {
            const pairs = Math.min(counts[i], counts[batchSize - i]);
            ans += pairs;
            counts[i] -= pairs;
            counts[batchSize - i] -= pairs;
        }
    }

    const memo = new Map();
    function dfs(rem, arr) {
        const key = rem + ':' + arr.join(',');
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        for (let i = 1; i < batchSize; ++i) {
            if (arr[i] > 0) {
                arr[i]--;
                const gained = rem === 0 ? 1 : 0;
                const nxtRem = (rem + i) % batchSize;
                res = Math.max(res, gained + dfs(nxtRem, arr));
                arr[i]++;
            }
        }
        memo.set(key, res);
        return res;
    }

    return ans + dfs(0, counts);
};
